package com.arjunren.bus;
import java.io.*;import java.nio.charset.StandardCharsets;import java.sql.*;
public final class Database{private final String url;public Database(String url){this.url=url;}public Connection connection()throws SQLException{return DriverManager.getConnection(url,System.getenv().getOrDefault("DB_USER","sa"),System.getenv().getOrDefault("DB_PASSWORD",""));}public void migrate(){try(var in=Database.class.getResourceAsStream("/db/migration.sql")){if(in==null)throw new IllegalStateException("Migration missing");var sql=new String(in.readAllBytes(),StandardCharsets.UTF_8);try(var c=connection();var s=c.createStatement()){for(var statement:sql.split(";"))if(!statement.isBlank())s.execute(statement);}}catch(Exception e){throw new IllegalStateException("Database migration failed",e);}}}
